import { Test, TestingModule } from '@nestjs/testing';
import { EventhubService } from './config/eventhub/eventhub.service';
import { AppController } from '@/app.controller';
import { AppService } from '@/app.service';

describe('AppController', () => {
  let appController: AppController;

  beforeEach(async () => {
    const app: TestingModule = await Test.createTestingModule({
      controllers: [AppController],
      providers: [
        AppService,
        {
          provide: EventhubService,
          useValue: {
            pubSubName: 'test-pubsub',
          },
        },
      ],
    }).compile();

    appController = app.get<AppController>(AppController);
  });

  describe('root', () => {
    it('should return "Hello World!"', () => {
      expect(appController.getHello()).toBe('mesx/order-data-ingestion');
    });
  });
});

import { Controller, Get } from '@nestjs/common';
import { EventhubService } from './config/eventhub/eventhub.service';
import { SubscribeMetaDataDto } from './dapr/dtos/subscribe-metadata.dto';
import { AppService } from '@/app.service';

@Controller()
export class AppController {
  public constructor(
    private readonly appService: AppService,
    private readonly pubSubService: EventhubService,
  ) {}

  @Get()
  public getHello(): string {
    return this.appService.getHello();
  }

  @Get('/dapr/subscribe')
  public subscribeMetaData(): Array<SubscribeMetaDataDto> {
    return [
      {
        pubsubname: this.pubSubService.pubSubName,
        route: `/${this.pubSubService.topicPlants}`,
        topic: this.pubSubService.topicPlants,
      },
    ];
  }
}

