@Global()
@Module({
  exports: [AppLogger],
  imports: [LoggerConfigModule],
  providers: [
    {
      inject: [LoggerConfigService],
      provide: AppLogger,
      useFactory: async (
        loggerConfigService: LoggerConfigService,
      ): Promise<AppLogger> => {
        const appLogger = new AppLogger(loggerConfigService);
        await appLogger.init(); // Ensure async initialization is handled before returning
        return appLogger;
      },
    },
  ],
})
export class AppLoggerModule {}

import { JobsLoggerService } from '@mesx/common-lib';
import { Injectable, LogLevel } from '@nestjs/common';
import { LoggerConfigService } from '@/config/logger/logger-config.service';

@Injectable()
export class AppLogger extends JobsLoggerService {
  public constructor(
    private readonly loggerConfigService: LoggerConfigService,
  ) {
    // Retrieve log level from environment
    super('log');
  }

  public async init(minLogLevel?: LogLevel): Promise<void> {
    const logLevel =
      minLogLevel ?? (await this.loggerConfigService.orderDiLogLevel());
    super.updateMinLogLevel(logLevel);
  }
}

import { JobsLogContext } from '@mesx/common-lib';

/**
 * Creates a log context object for job logging.
 * @param serviceName The name of the service generating the log.
 * @param method The method or operation being logged.
 * @param plant (Optional) The plant identifier.
 * @param object (Optional) The object related to the log entry.
 * @param userId (Optional) The user ID associated with the log entry.
 * @returns A JobsLogContext object containing the provided context information.
 */
export function createLogContext(
  serviceName: string,
  method: string,
  plant?: number,
  object?: string,
  userId?: string,
): JobsLogContext {
  return {
    method,
    object,
    plant,
    service: serviceName,
    userId,
  };
}

