import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class MssqlService implements OnModuleInit {
  private readonly context: JobsLogContext = {
    method: '',
    service: MssqlService.name,
  };

  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get type(): string {
    return this.configService.get<string>('mssql.type') ?? '';
  }

  public get host(): string {
    return this.configService.get<string>('mssql.host') ?? '';
  }

  public get port(): number {
    return this.configService.get<number>('mssql.port') ?? 1433;
  }

  public get username(): string {
    return this.configService.get<string>('mssql.username') ?? '';
  }

  public get password(): string {
    return this.configService.get<string>('mssql.password') ?? '';
  }

  public get database(): string {
    return this.configService.get<string>('mssql.database') ?? '';
  }

  public get synchronize(): boolean {
    return this.configService.get<boolean>('mssql.synchronize') ?? false;
  }

  public get useManagedIdentity(): boolean {
    return this.managedIdentityClientId?.trim().length > 0;
  }

  public get managedIdentityClientId(): string {
    return (
      this.configService.get<string>('mssql.managedIdentityClientId') ?? ''
    );
  }

  public get encrypt(): boolean {
    return this.configService.get<boolean>('mssql.encrypt') ?? false;
  }

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  private checkConfiguration(): void {
    this.context.method = 'checkConfiguration';
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'mssql.host', value: this.host },
      { key: 'mssql.database', value: this.database },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          this.context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    // Check the conditional logic for authentication
    const hasUsernameAndPassword = this.username && this.password;
    const hasManagedIdentity =
      this.useManagedIdentity && this.managedIdentityClientId;

    if (!hasUsernameAndPassword && !hasManagedIdentity) {
      this.customLogger.error(
        'Either username/password or managedIdentityClientId/useManagedIdentity must be provided',
        this.context,
      );
      throw new Error(
        'Configuration error: You must set either username/password or managedIdentityClientId/useManagedIdentity',
      );
    }

    this.customLogger.log(
      'All required MSSQL configurations are properly set',
      this.context,
    );
  }
}

