@Controller('')
export class DaprController {
  public constructor(
    private readonly eventhubSdkConfigService: EventhubSdkConfigService,
    private readonly daprService: DaprService,
    private readonly customLogger: AppLogger,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly materialGroupMemberConvertService: MaterialGroupMemberConvertService,
    private readonly daprServiceApi: DaprServiceApi,
  ) {}

  /**
   * Process a standard event with common logging
   * @param request Request
   * @param methodName Method name for logging
   * @param topic topic name for telemetry
   * @returns Promise<string>
   */
  private async processStandardEvent(
    request: Request,
    methodName: string,
    topic: string,
  ): Promise<string> {
    const startTime = Date.now();
    const event = request.body;
    const plantCode = event?.PLANT || event?.S_SITE;
    if (topic) {
      try {
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.RECEIVED,
          plantCode,
          topic,
        );
      } catch {
        // Silent fail - don't break processing if telemetry fails
      }
    }
    try {
      const result = await this.daprService.handleMessage(event);
      const duration = Date.now() - startTime;
      if (result.processed) {
        telemetryMetrics.trackEventProcessingDuration(
          duration,
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
      }
      return `OK${methodName}`;
    } catch (error) {
      const duration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        duration,
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      throw error;
    }
  }

  @Post(bindings.bindingAlert)
  public async receiveEventAlert(@Req() request: Request): Promise<string> {
    const context: JobsLogContext = {
      method: 'checkAlertCodeAndCategory:bindingAlert',
      service: 'DaprService',
    };
    if (!checkAlertCodeAndCategory(this.customLogger, context, request.body))
      return 'OK';
    return this.processStandardEvent(request, 'receiveEventAlert', 'alert');
  }

  @Post(bindings.bindingAlertConfig)
  public async receiveEventAlertConfig(
    @Req() request: Request,
  ): Promise<string> {
    const context: JobsLogContext = {
      method: 'checkAlertCodeAndCategory:bindingAlertConfig',
      service: 'DaprService',
    };
    if (!checkAlertCodeAndCategory(this.customLogger, context, request.body))
      return 'OK';
    return this.processStandardEvent(
      request,
      'receiveEventAlertConfig',
      'alert-config',
    );
  }

  @Post(bindings.bindingMaterialDtl)
  public async receiveEventMaterialDtl(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventMaterialDtl',
      'material-dtl',
    );
  }

  @Post(bindings.bindingMaterialGroup)
  public async receiveEventMaterialGroup(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventMaterialGroup',
      'material-group',
    );
  }

  @Post(bindings.bindingMaterialGroupMember)
  public async receiveEventMaterialGroupMember(
    @Req() request: Request,
  ): Promise<string> {
    const context: JobsLogContext = {
      method: 'checkPayloadConsistency:bindingMaterialGroupMember',
      service: 'DaprService',
    };
    if (!checkPayloadConsistency(this.customLogger, context, request.body))
      return 'OK';
    const converted = await this.materialGroupMemberConvertService.convert(
      request.body,
    );
    request.body = converted;
    return this.processStandardEvent(
      request,
      'receiveEventMaterialGroupMember',
      'material-group-member',
    );
  }

  @Post(bindings.bindingLauncherKpi)
  public async receiveEventLauncherKpi(
    @Req() request: Request,
  ): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    const lancherKpiMessage = request.body;
    const context: JobsLogContext = {
      method: 'checkPayloadConsistency:bindingLauncherKpi',
      service: 'DaprService',
    };
    if (
      !checkPayloadConsistency(this.customLogger, context, lancherKpiMessage)
    ) {
      return 'NOK PAYLOAD';
    }
    // Filter launcher KPI records: only process LAUNCHER_WAITING_TIME
    if (
      request.body.__source_table === 'C_CURRENT_KPI_VALUE' &&
      request.body.S_KPI_NAME !== 'LAUNCHER_WAITING_TIME'
    ) {
      const jobsLogContext: JobsLogContext = {
        method: 'receiveEventLauncherKpi',
        service: 'DaprService',
      };
      this.customLogger.verbose(
        `Skipping KPI record with S_KPI_NAME='${request.body.S_KPI_NAME}' (only LAUNCHER_WAITING_TIME is processed)`,
        jobsLogContext,
      );
      return 'OK';
    }
    return this.processStandardEvent(
      request,
      'receiveEventLauncherKpi',
      'launcher-kpi',
    );
  }

  @Post(bindings.bindingMtlTrans)
  public async receiveEventMtlTrans(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventMtlTrans',
      'mtl-trans',
    );
  }

  @Post(bindings.bindingPickingOrder)
  public async receiveEventPickingOrder(
    @Req() request: Request,
  ): Promise<string> {
    const sequenceNumber =
      request.headers['x-opt-sequence-number'] ||
      (request.headers['X-Opt-Sequence-Number'] as string);

    const pickingOrderMessage = request.body;
    const context: JobsLogContext = {
      method: 'checkPayloadConsistency:bindingPickingOrder',
      service: 'DaprService',
    };
    this.customLogger.debug(
      `============== ${sequenceNumber} Start ${pickingOrderMessage?.S_SITE} picking order id  ${pickingOrderMessage?.S_SHOP_ORDER}  =======================`,
      context,
    );

    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    if (
      !checkPayloadConsistency(this.customLogger, context, pickingOrderMessage)
    ) {
      return 'NOK PAYLOAD';
    }

    this.processStandardEvent(
      request,
      'receiveEventPickingOrder',
      'picking-order',
    );
    request.body.__source_table = 'buffer';
    return this.processStandardEvent(
      request,
      'receiveEventPickingOrder',
      'picking-order',
    );
  }

  @Post(bindings.bindingProductionOrder)
  public async receiveEventProductionOrder(
    @Req() request: Request,
  ): Promise<string> {
    const sequenceNumber =
      request.headers['x-opt-sequence-number'] ||
      (request.headers['X-Opt-Sequence-Number'] as string);

    const shopOrderMessage = request.body;
    const context: JobsLogContext = {
      method: 'checkPayloadConsistency:bindingShopOrder',
      service: 'DaprService',
    };
    this.customLogger.debug(
      `============== ${sequenceNumber} Start ${shopOrderMessage?.SITE} shop order id  ${shopOrderMessage?.SHOP_ORDER}  =======================`,
      context,
    );

    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    return this.processStandardEvent(
      request,
      'receiveEventProductionOrder',
      'production-order',
    );
  }

  @Post(bindings.bindingWorkCenterList)
  public async receiveEventWorkCenter(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventWorkCenter',
      'workcenter',
    );
  }

  @Post(bindings.bindingShopOrder)
  public async receiveEventShopOrder(@Req() request: Request): Promise<string> {
    const sequenceNumber =
      request.headers['x-opt-sequence-number'] ||
      (request.headers['X-Opt-Sequence-Number'] as string);

    const shopOrderMessage = request.body;
    const context: JobsLogContext = {
      method: 'checkPayloadConsistency:bindingShopOrder',
      service: 'DaprService',
    };
    this.customLogger.debug(
      `============== ${sequenceNumber} Start ${shopOrderMessage?.SITE} shop order id  ${shopOrderMessage?.SHOP_ORDER}  =======================`,
      context,
    );
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    if (
      !checkPayloadConsistency(this.customLogger, context, shopOrderMessage)
    ) {
      return 'NOK PAYLOAD';
    }
    return this.processStandardEvent(
      request,
      'receiveEventShopOrder',
      'shop-order',
    );
  }

  @Post(bindings.topicPlants)
  public async initPlant(@Req() request: Request): Promise<string> {
    const context = DaprService.createLogContext('initPlant');
    try {
      const data = request.body;
      await this.subscribeMessageService.handleMessage(data);
      await this.daprService.initializePlant();
      await this.daprServiceApi.initializePlant();

      this.customLogger.debug(`Updated Plants List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }
}

