@Injectable()
export class DaprService implements OnModuleInit, BeforeApplicationShutdown {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprService.name, userId };
  }

  private readonly processingQueue: Record<string, boolean> = {
    alert: false,
    alertConfig: false,
    buffer: false,
    launcherKpi: false,
    materialDtl: false,
    materialGroup: false,
    materialGroupMember: false,
    pickingOrder: false,
    productionOrder: false,
    shopOrder: false,
  };

  private readonly daprClient: DaprClient;

  private plantList: Array<PlantsResponseDto> = [];

  private excludedPlants: Set<string> = new Set();

  private readonly inMemoryQueue: {
    alert: Array<RedisMessage>;
    alertConfig: Array<RedisMessage>;
    pickingOrder: Array<RedisMessage>;
    productionOrder: Array<RedisMessage>;
    shopOrder: Array<RedisMessage>;
    materialDtl: Array<RedisMessage>;
    materialGroup: Array<RedisMessage>;
    materialGroupMember: Array<RedisMessage>;
    buffer: Array<RedisMessage>;
    launcherKpi: Array<RedisMessage>;
    workcenter: Array<RedisMessage>;
  } = {
    alert: [],
    alertConfig: [],
    buffer: [],
    launcherKpi: [],
    materialDtl: [],
    materialGroup: [],
    materialGroupMember: [],
    pickingOrder: [],
    productionOrder: [],
    shopOrder: [],
    workcenter: [],
  };

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly mappingService: MappingService,
    private readonly eventEmitter: EventEmitter2,
    private readonly redisConfigService: RedisConfigService,
    private readonly fileShareConfigService: FileShareConfigService,
    private readonly ingestionPolicyConfigService: IngestionPolicyConfigService,
    private readonly mutexManagerService: MutexManagerService,
    private readonly orderService: OrderService,
    private readonly ingestionEventTrackingService: IngestionEventTrackingService,
    private readonly subscribeMessageService: SubscribeMessageService,
  ) {
    this.daprClient = new DaprClient();
    this.mutexManagerService.getMutex('pickingOrder');
    this.mutexManagerService.getMutex('productionOrder');
    this.mutexManagerService.getMutex('shopOrder');
    this.mutexManagerService.getMutex('materialDtl');
    this.mutexManagerService.getMutex('materialGroup');
    this.mutexManagerService.getMutex('materialGroupMember');
    this.mutexManagerService.getMutex('buffer');
    this.mutexManagerService.getMutex('alert');
    this.mutexManagerService.getMutex('alertConfig');
    this.mutexManagerService.getMutex('launcherKpi');
    this.mutexManagerService.getMutex('workcenter');
  }

  /**
   * Handles tasks that need to be performed before the application shuts down.
   * @param signal - The signal that triggered the shutdown.
   * @returns A promise that resolves when the shutdown tasks are complete.
   */
  public async beforeApplicationShutdown(signal: string): Promise<void> {
    const { queueBackupBasePath } = this.fileShareConfigService;
    const microServiceName = 'order-di';
    await beforeApplicationShutdown(
      this.customLogger,
      this.inMemoryQueue,
      queueBackupBasePath,
      microServiceName,
      signal,
    );
  }

  public async onModuleInit(): Promise<void> {
    await this.loadExcludedPlants();
    await this.initializePlant();
    await this.initializeQueues();
  }

  private async loadExcludedPlants(): Promise<void> {
    const context = DaprService.createLogContext('loadExcludedPlants');
    try {
      this.excludedPlants =
        await this.ingestionPolicyConfigService.getExcludedPlants();
    } catch (error) {
      this.excludedPlants = new Set();
      this.customLogger.error(
        `Failed to load excluded plants: ${error.message ?? error}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Initializes the plant list by fetching it from the Redis store.
   * Logs a debug message indicating the start of the initialization process.
   * @returns A promise that resolves when the plant list has been initialized.
   */
  public async initializePlant(): Promise<void> {
    const context = DaprService.createLogContext('initializePlant');
    try {
      this.plantList = await getListPlant(
        this.customLogger,
        this.daprClient,
        this.subscribeMessageService,
        this.redisConfigService.redisStoreAmr,
        this.redisConfigService.redisPlantKey,
      );
      this.customLogger.log(
        `Updated Plant List: ${JSON.stringify(this.plantList)}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to get plant list: ${error.message}`,
        context,
        error,
      );
    }
  }

  private async initializeQueues(): Promise<void> {
    const { queueBackupBasePath } = this.fileShareConfigService;
    const microServiceName = 'order-di';
    await loadQueuesFromFileShare(
      this.customLogger,
      queueBackupBasePath,
      microServiceName,
      this.inMemoryQueue,
    );
    this.checkAndProcessQueues();
  }

  private checkAndProcessQueues(): void {
    const context = DaprService.createLogContext('checkAndProcessQueues');
    for (const [queueName, queueData] of Object.entries(this.inMemoryQueue)) {
      if (queueData && queueData.length > 0) {
        if (this.processingQueue[queueName]) {
          this.customLogger.verbose(
            `Queue ${queueName} is already being processed, skipping.`,
            context,
          );
        } else {
          this.processMessageQueue(queueName);
        }
      } else {
        this.customLogger.verbose(
          `Queue ${queueName} is empty, skipping processing.`,
          context,
        );
      }
    }
  }

  /**
   * Update data without using cache if there's no result from Redis,
   * and after confirming whether the data is inserted or not.
   * @param keysValueArray - Array of key-value pairs
   * @param mappedData - The mapped data
   * @param operation - The operation type (e.g., 'u' for update)
   * @returns - Returns true if data is updated, false otherwise
   */
  private async updateDataWithoutCache(
    keysValueArray: KeysValueArray,
    mappedData: MappedOutput,
    operation: string,
  ): Promise<boolean> {
    // This is a custom situation in the case of orders. In other cases, we can use EventEmitter to dynamically adjust the function.
    const operationInfo = {
      name: '',
      srcLocation: 'updateDataWitoutCache',
    };
    const context = DaprService.createLogContext(
      'updateDataWithoutCache',
      mappedData?.plant,
      JSON.stringify(keysValueArray),
    );
    operationInfo.name = 'Find Order and Source Table (SQL)';
    const resultOrder = await execAndLog(
      this.customLogger,
      context,
      () => this.orderService.findOrder(keysValueArray),
      operationInfo,
      { keysValueArray },
    );

    this.customLogger.debug(
      `Received from find Order -  result: ${JSON.stringify(resultOrder)}`,
      context,
    );

    // 🔁 Early return to reduce nesting
    if (!resultOrder) {
      return false;
    }

    const data = {
      ...mappedData,
      [resultOrder.pickingOrderId ? 'pickingOrderId' : 'productionOrderId']:
        resultOrder.pickingOrderId || resultOrder.productionOrderId,
    };

    await emitSqlEvent(
      this.customLogger,
      context,
      this.eventEmitter,
      resultOrder.source_table,
      data,
      operation,
    );

    return true;
  }

  /**
   * Process the message
   * @param message Mapped Data to process
   * @param redisStoreAmr used for dapr state store (Amr)
   */
  private async processMessage(
    message: RedisMessage,
    redisStoreAmr: string,
  ): Promise<void> {
    const {
      mappedData,
      destination,
      operation,
      keysValueArray,
      cacheTreatment,
      ingestionEventTracking,
    } = message;
    const plant = mappedData?.plant;
    const context = DaprService.createLogContext(
      'processMessage',
      mappedData?.plant,
    );
    const startTime = Date.now();
    try {
      if (!operation || !keysValueArray) {
        return;
      }
      if (operation !== 'r' && ingestionEventTracking) {
        const validateAndTrackIngestionEventTracking: boolean =
          await validateAndTrackChanges(
            this.customLogger,
            this.ingestionEventTrackingService,
            ingestionEventTracking,
          );
        if (!validateAndTrackIngestionEventTracking) {
          return;
        }
        await this.ingestionEventTrackingService.upsertCache(
          ingestionEventTracking,
        );
      }
      await (cacheTreatment
        ? this.processMessageWithCache(
            plant,
            message,
            keysValueArray,
            redisStoreAmr,
          )
        : emitSqlEvent(
            this.customLogger,
            context,
            this.eventEmitter,
            destination,
            mappedData,
            operation,
          ));
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
      );
    }
  }

  /**
   * Process the message with Cache Processing Logic
   * @param plant Plant Id
   * @param message Redis Message,
   * @param keysValueArray Keys Value Array,
   * @param redisStoreAmr redisStore AMR
   */
  private async processMessageWithCache(
    plant: number,
    message: RedisMessage,
    keysValueArray: KeysValueArray,
    redisStoreAmr: string,
  ): Promise<void> {
    const context = DaprService.createLogContext(
      'processMessageWithCache',
      plant,
    );
    const { mappedData, keysValue, destination, sourceTable, operation } =
      message;

    const cacheKey = `${keysValue}.${operation}`;
    const operationInfo = {
      name: '',
      srcLocation: 'processMessage',
    };
    const operationDetails = {
      cacheKey,
      plant,
    };
    // This lock is only for use case picking order, shop order, production order as there i 3 queue for 2 destination tables
    this.customLogger.debug(`locking key for ${cacheKey}`, context);
    operationInfo.name = 'Acquire lock for order Id';
    const release = await execAndLog(
      this.customLogger,
      context,
      () =>
        acquireLockWithTimeout(
          this.customLogger,
          context,
          this.mutexManagerService,
          cacheKey,
        ),
      operationInfo,
      operationDetails,
    );
    if (!release) {
      this.customLogger.error(
        `Error: Failed to acquire lock for ${cacheKey}, skipping processing.`,
        context,
      );
      await moveToDeadLetterQueue(
        this.customLogger,
        context,
        redisStoreAmr,
        this.daprClient,
        cacheKey,
        message,
        MESSAGE_ACTION.GETORDERID,
      );
      return;
    }
    try {
      this.customLogger.debug(`Checking state key: ${cacheKey}`, context);
      operationInfo.name = 'Get state';
      const result = await execAndLog(
        this.customLogger,
        context,
        () => this.daprClient.state.get(redisStoreAmr, cacheKey),
        operationInfo,
        operationDetails,
      );

      // Update data without using cache if there's no result from Redis,
      // And after confirming whether the data is inserted or not.
      if (!result.valueOf() && operation === 'u') {
        operationInfo.name = 'UpdateDataWithoutCache';
        const dataUpdated = await execAndLog(
          this.customLogger,
          context,
          () =>
            this.updateDataWithoutCache(keysValueArray, mappedData, operation),
          operationInfo,
          { keysValueArray },
        );
        if (dataUpdated) {
          return;
        }
      }

      // Caching the first wave of data
      if (
        !result.valueOf() ||
        Object.values(result.valueOf())[0].sourceTable === sourceTable
      ) {
        if (!sourceTable) {
          return;
        }

        const recordCache = {
          destination,
          keysValue,
          mappedData,
          sourceTable,
        };

        await appendAndSaveToCache(
          this.customLogger,
          this.daprClient,
          this.redisConfigService.redisStoreAmr,
          cacheKey,
          result,
          recordCache,
        );
        return;
      }
      const redisData = Object.values(result.valueOf()).at(-1).mappedData;
      const destinationRedis = Object.values(result.valueOf()).at(
        -1,
      ).destination;

      const destinationService = destinationRedis + destination;
      const completedData = { ...redisData, ...mappedData }; // Append the data
      // Unstack the oldest records (FIFO logic)

      operationInfo.name = 'Delete state';
      await execAndLog(
        this.customLogger,
        context,
        async () => {
          // We processed the last records => Cache can be freed
          this.customLogger.debug(`Deleting state key: ${cacheKey}`, context);
          return this.daprClient.state.delete(redisStoreAmr, cacheKey);
        },
        operationInfo,
        operationDetails,
      );
      this.customLogger.debug(`End of locking for ${cacheKey}`, context);
      release?.();
      if (!operation) {
        return;
      }
      await emitSqlEvent(
        this.customLogger,
        context,
        this.eventEmitter,
        destinationService,
        completedData,
        operation,
      );
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
        error.stack,
      );
      await moveToDeadLetterQueue(
        this.customLogger,
        context,
        redisStoreAmr,
        this.daprClient,
        cacheKey,
        message,
        MESSAGE_ACTION.GETORDERID,
      );
    } finally {
      this.customLogger.debug(
        `End of locking for ${cacheKey} at ${Date.now()} `,
        context,
      );
      release?.();
    }
  }

  /**
   * Process message in the queue
   * @param queueKey - Queue
   * @returns void
   */
  private async processNextMessage(queueKey: string): Promise<void> {
    const context = DaprService.createLogContext('processNextMessage');

    try {
      const messageQueue =
        this.inMemoryQueue[queueKey as keyof typeof this.inMemoryQueue];
      // Exit if the queue is empty
      if (messageQueue.length === 0) {
        this.customLogger.verbose(
          `No messages left in queue ${queueKey}.`,
          context,
        );
        return; // Exit when there are no more messages to process
      }

      // Process the first message in the queue
      const message = messageQueue[0];
      if (!message) {
        return; //
      }
      const plant = message?.mappedData?.plant;

      try {
        this.customLogger.debug(
          `Plant ${plant} - Processing message: ${JSON.stringify(message)} for ${queueKey}`,
          context,
        );

        // Process the message
        await this.processMessage(
          message,
          this.redisConfigService.redisStoreAmr,
        );

        this.customLogger.verbose(
          `Plant ${plant} - Message processed for ${queueKey}, removing from queue.`,
          context,
        );

        // Remove the processed message
        await removeMessageQueue(
          this.customLogger,
          this.mutexManagerService,
          this.daprClient,
          {
            inMemoryQueue: this.inMemoryQueue,
            processingQueue: this.processingQueue,
            queueKey,
            redisStoreNameAmr: this.redisConfigService.redisStoreAmr,
          },
          message,
        );
      } catch (error) {
        this.customLogger.error(
          `Plant ${plant} - Error processing message for ${queueKey}: ${error.message ?? error.stack}`,
          context,
        );
        await moveToDeadLetterQueue(
          this.customLogger,
          context,
          this.redisConfigService.redisStoreAmr,
          this.daprClient,
          queueKey,
          message,
          MESSAGE_ACTION.ERROR,
        ); // Move to DLQ if error occurs
      }

      // Continue processing the next message
      await this.processNextMessage(queueKey); // Recursive call to process the next message
    } catch (error) {
      this.customLogger.error(
        `Error retrieving Redis queue for ${queueKey}: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  /**
   * Process Message Queue Sequentially using Recursion
   * @param queueKey Queue Key
   */
  private async processMessageQueue(queueKey: string): Promise<void> {
    const context = DaprService.createLogContext('processMessageQueue');

    try {
      // Mark processing as ongoing for this queue
      this.processingQueue[queueKey] = true;
      // Start processing with the recursive function
      await this.processNextMessage(queueKey);
    } finally {
      this.processingQueue[queueKey] = false;
      this.customLogger.verbose(
        `Finished processing queue for ${queueKey}.`,
        context,
      );
    }
  }

  /**
   * Message handler
   * @param record Record To handle
   */
  public async handleMessage(
    record: CombinedDtoWithIndex,
  ): Promise<{ processed: boolean; reason?: string }> {
    const context = DaprService.createLogContext('handleMessage');
    this.customLogger.debug(
      `Received - payload: ${JSON.stringify(record)}`,
      context,
    );
    incrementPendingMessageCount();
    const dateStart = Date.now();
    const shopOrder = record.SHOP_ORDER ?? record.S_SHOP_ORDER ?? 'unknown';
    const operationInfo = {
      name: '',
      srcLocation: 'handleMessage',
    };
    const operationDetails = {
      shopOrder,
    };

    try {
      if (!checkPayloadConsistency(this.customLogger, context, record))
        return { processed: false, reason: 'Payload consistency check failed' };

      const { __source_table: sourceTable, __op: operation } = record;
      if (!sourceTable)
        return { processed: false, reason: 'Source table is missing' };

      const destination = this.mappingService.getDestinationTable(sourceTable);
      // Condition for shopOrder as it is empty the destination
      const queueKey = destination || 'shopOrder'; // Unique queue key for each binding
      await appendAndSaveToCacheQueue(
        this.customLogger,
        this.daprClient,
        this.redisConfigService.redisStoreAmr,
        {
          mappingService: this.mappingService,
          serviceMutexes: this.mutexManagerService,
        },
        this.inMemoryQueue,
        this.processingQueue,
        this.plantList,
        this.excludedPlants,
        {
          key: queueKey,
          operation,
          record,
          sourceTable,
        },
      );
      if (this.processingQueue[queueKey]) {
        this.customLogger.debug(
          `${shopOrder}: queue ${queueKey} is already processing`,
          context,
        );
        return {
          processed: false,
          reason: `message ${queueKey} is already in processing`,
        };
      }

      this.customLogger.debug(
        `Triggering queue processing ${queueKey} from order: ${shopOrder}`,
        context,
      );
      this.processMessageQueue(queueKey);
      return { processed: true };
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.stack ?? error.message ?? JSON.stringify(error)}`,
        context,
      );
      return { processed: false, reason: error.message };
    } finally {
      if (record) {
        operationInfo.name = 'handleMessage function runtime';
        await execAndLog(
          this.customLogger,
          context,
          async () => {},
          operationInfo,
          operationDetails,
          dateStart,
        );
      }
      decrementPendingMessageCount();
    }
  }
}

