// Removed unused import LauncherKpiService

@Injectable()
export class EventhubSdkLauncherKpiService
  implements OnModuleInit, OnModuleDestroy
{
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: EventhubSdkLauncherKpiService.name,
      userId,
    };
  }

  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  public constructor(
    private readonly configService: EventhubSdkConfigService,
    private readonly daprService: DaprServiceApi,
    private readonly logger: AppLogger,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context =
      EventhubSdkLauncherKpiService.createLogContext('initialize');
    try {
      const useEventhubSDK = await this.configService.useEventhubSDK();
      if (!useEventhubSDK) {
        this.logger.warn(
          `[LauncherKpi] Skipping EventHub SDK initialization, useEventhubSDK: ${useEventhubSDK}`,
          context,
        );
        return;
      }

      this.logger.log('Initializing container EventHub service', context);

      // Get EventHub configuration using the helper method
      const eventHubConfig = this.configService.getLauncherKpiConfig();

      // Initialize EventHub clients
      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      // Create message processor
      const enhancedProcessor = this.createMessageProcessor();
      // Wrap enhanced processor to match MessageProcessor interface
      const processor: MessageProcessor = {
        processMessage: async (message, sequenceNumber, partitionId) => {
          await enhancedProcessor.processMessage(
            message,
            sequenceNumber,
            partitionId,
          );
        },
      };

      // Configure error recovery
      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };

      // Subscribe to EventHub with enhanced features
      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval: this.configService.launcherKpiCheckpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: 'EventHubLauncherKpiEnhancedService',
          topicName: 'launcher-kpi',
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          maxBatchSize: 1,
          enableCheckpointing: true,
        },
      });

      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;

      this.logger.log(
        'Enhanced container EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize Enhanced container EventHub service: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = EventhubSdkLauncherKpiService.createLogContext('cleanup');
    try {
      this.logger.log(
        'Cleaning up Enhanced container EventHub service',
        context,
      );

      // Set shutdown state to true
      this.shutdownState.value = true;

      // Perform final checkpoints
      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            consumerGroup: this.configService.launcherKpiconsumerGroup,
            eventHubName: this.configService.eventHubLauncherKpiName,
            eventHubNamespace: this.configService.eventHubLauncherKpiNamespace,
            checkpointInterval:
              this.configService.launcherKpiCheckpointInterval,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      // Unsubscribe from EventHub
      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          'EventHubLauncherKpiEnhancedService',
          this.logger,
        );
        this.subscription = null;
      }

      // Clean up EventHub clients
      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }

      this.partitionInfo = null;

      this.logger.log(
        'Enhanced container EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during Enhanced container EventHub service cleanup: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Create message processor specific to container with validation and masking
   * @returns MessageProcessor configured for container processing
   */
  private createMessageProcessor(): EnhancedMessageProcessor {
    return {
      processMessage: async (
        message: CombinedDtoWithIndex,
        sequenceNumber: string,
        partitionId?: string,
      ): Promise<ProcessingResult | void> => {
        const startTime = Date.now();
        const plantCode = String(message.S_SITE);
        try {
          if (
            !checkPayloadConsistency(
              this.logger,
              EventhubSdkLauncherKpiService.createLogContext('validateMessage'),
              message,
            )
          ) {
            const duration = Date.now() - startTime;
            telemetryMetrics.trackEventProcessingDuration(
              duration,
              PROCESSING_STATUS.INVALID,
              plantCode,
              'launcher-kpi',
              partitionId,
            );
            telemetryMetrics.trackEventProcessed(
              PROCESSING_STATUS.INVALID,
              plantCode,
              'launcher-kpi',
              partitionId,
            );
            return undefined;
          }
          // Filter launcher KPI records: only process LAUNCHER_WAITING_TIME

          if (
            message.__source_table === 'C_CURRENT_KPI_VALUE' &&
            message.S_KPI_NAME !== 'LAUNCHER_WAITING_TIME'
          ) {
            const duration = Date.now() - startTime;
            this.logger.verbose(
              `Skipping KPI record with S_KPI_NAME='${message.S_KPI_NAME}' (only LAUNCHER_WAITING_TIME is processed)`,
              EventhubSdkLauncherKpiService.createLogContext('processMessage'),
            );
            telemetryMetrics.trackEventProcessingDuration(
              duration,
              PROCESSING_STATUS.FILTERED,
              plantCode,
              'launcher-kpi',
              partitionId,
            );
            telemetryMetrics.trackEventProcessed(
              PROCESSING_STATUS.FILTERED,
              plantCode,
              'launcher-kpi',
              partitionId,
            );
            return { status: 'filtered', plantCode };
          }
          const result = await this.daprService.handleMessage(message);
          this.logger.log(
            '[EventHubSDK] launcherKpi message processed',
            EventhubSdkLauncherKpiService.createLogContext('processMessage'),
          );
          const duration = Date.now() - startTime;
          if (result.processed) {
            telemetryMetrics.trackEventProcessingDuration(
              duration,
              PROCESSING_STATUS.PROCESSED,
              String(plantCode),
              'launcher-kpi',
              partitionId,
            );
            telemetryMetrics.trackEventProcessed(
              PROCESSING_STATUS.PROCESSED,
              String(plantCode),
              'launcher-kpi',
              partitionId,
            );
          }
          return { status: 'processed', plantCode };
        } catch (error) {
          const duration = Date.now() - startTime;
          telemetryMetrics.trackEventProcessingDuration(
            duration,
            PROCESSING_STATUS.INVALID,
            String(plantCode),
            'launcher-kpi',
            partitionId,
          );
          telemetryMetrics.trackEventProcessed(
            PROCESSING_STATUS.INVALID,
            String(plantCode),
