// Test the exponentialBackoffRetry function
describe('exponentialBackoffRetry', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should retry the operation and succeed', async () => {
    const mockOperation = jest
      .fn()
      .mockRejectedValueOnce(
        Object.assign(new Error('Some retryable error'), {
          name: 'AbortError',
        }),
      )
      .mockResolvedValue('Success');

    const result = await exponentialBackoffRetry(
      mockLogger,
      context,
      mockOperation,
      2, // Reduced retries
      10, // Reduced baseDelayMs
      true, // Enable jitter
      1, // Initial attempt
      1, // Reduced maxBackoff
    );

    expect(result).toBe('Success');
    expect(mockOperation).toHaveBeenCalledTimes(2); // Initial + 1 retry
    expect(mockLogger.warn).toHaveBeenCalledWith(
      expect.stringContaining('Retrying operation'),
      expect.objectContaining({
        method: 'exponentialBackoffRetryTest',
        service: 'retryService',
      }),
    );
  });

  it('should throw after exceeding retries', async () => {
    const mockOperation = jest.fn().mockRejectedValue(
      Object.assign(new Error('Persistent error'), {
        code: 429,
      }),
    );

    await expect(
      exponentialBackoffRetry(
        mockLogger,
        context,
        mockOperation,
        2, // Reduced retries
        10, // Reduced baseDelayMs
        true, // Enable jitter
        1, // Initial attempt
        1, // Reduced maxBackoff
      ),
    ).rejects.toThrow('Persistent error');

    expect(mockOperation).toHaveBeenCalledTimes(2); // Ensure retries were exhausted
    expect(mockLogger.error).toHaveBeenCalledWith(
      expect.stringContaining('Operation failed after 2 retries'),
      expect.objectContaining({
        method: 'exponentialBackoffRetryTest',
        service: 'retryService',
      }),
    );
  });

  it('should not retry on non-retryable error', async () => {
    const mockOperation = jest
      .fn()
      .mockRejectedValue(
        Object.assign(new Error('Non-retryable error'), { name: 'TypeError' }),
      );

    await expect(
      exponentialBackoffRetry(mockLogger, context, mockOperation),
    ).rejects.toThrow('Non-retryable error');

    expect(mockOperation).toHaveBeenCalledTimes(1); // No retry
    expect(mockLogger.error).toHaveBeenCalledWith(
      expect.stringContaining('Non-retryable error encountered'),
      expect.objectContaining({
        method: 'exponentialBackoffRetryTest',
        service: 'retryService',
      }),
    );
  });
});

import { randomInt } from 'node:crypto';
import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/common/logger/app-logger';
import { asyncSleep } from '@/common/sleep/sleep';

interface RetryableError {
  code?: number;
  name?: string;
  message?: string;
}
/**
 * Determines if the provided error is retryable based on its properties.
 * @param error The error object to check for retryability.
 * @returns True if the error is retryable, otherwise false.
 */
function isRetryableError(error: unknown): error is RetryableError {
  if (
    typeof error !== 'object' ||
    error === null ||
    (!('code' in error) && !('name' in error) && !('message' in error))
  ) {
    return false;
  }

  const errorN = error as RetryableError;

  return (
    errorN.code === 429 ||
    (typeof errorN.code === 'number' &&
      errorN.code >= 500 &&
      errorN.code < 600) ||
    (errorN.message?.includes('The client is closed') ?? false) ||
    (errorN.message?.includes('Socket closed unexpectedly') ?? false) ||
    errorN.name === 'AbortError' ||
    (errorN.name === 'ReplyError' &&
      ((errorN.message?.includes('TRYAGAIN') ?? false) ||
        (errorN.message?.includes('READONLY') ?? false)))
  );
}

/**
 * Calculates the delay for the next retry attempt using exponential backoff with a random jitter.
 * @param attempt - The current attempt number.
 * @param maxBackoff - The maximum backoff time in seconds.
 * @returns The calculated delay in milliseconds.
 */
export function calculateExponentialBackoffDelay(
  attempt: number,
  maxBackoff: number,
): number {
  const randomNumberMilliseconds = randomInt(0, 1000); // Random number between 0 and 1000
  const exponentialDelay = 2 ** attempt; // 2^n
  return Math.min(
    exponentialDelay * 1000 + randomNumberMilliseconds,
    maxBackoff * 1000,
  ); // Convert seconds to milliseconds
}

/**
 * Retries a given operation a specified number of times with an exponential backoff delay between attempts.
 * @template T The type of the result returned by the operation.
 * @param logger - Logger instance for logging.
 * @param context Job Log Context
 * @param operation - The operation to retry.
 * @param [retries] - Number of retry attempts.
 * @param [baseDelayMs] - Base delay between retries in milliseconds.
 * @param [jitter] - Whether to add randomness to the delay.
 * @param [attempt] - Current attempt number.
 * @param maxBackoff -max delay
 * @returns A promise that resolves to the result of the operation.
 * @throws Will throw an error if the operation fails after the specified number of retries.
 */
export async function exponentialBackoffRetry<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  retries = 5,
  baseDelayMs = 1000,
  jitter = true,
  attempt = 1,
  maxBackoff = 32,
): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    if (attempt >= retries) {
      logger.error(
        `Operation failed after ${retries} retries: ${(error as Error).message}`,
        context,
      );
      throw error;
    }
    if (!isRetryableError(error)) {
      logger.error(
        `Non-retryable error encountered: ${(error as Error).message}`,
        context,
      );
      throw error; // Non-retryable error, rethrow
    }

    // Calculate delay
    const delay = jitter
      ? calculateExponentialBackoffDelay(attempt, maxBackoff)
      : baseDelayMs * 2 ** (attempt - 1);
    logger.warn(
      `Retrying operation (${attempt}/${retries}) after error: ${(error as Error).message}`,
      context,
    );

    asyncSleep(delay);
    return exponentialBackoffRetry(
      logger,
      context,
      operation,
      retries,
      delay,
      jitter,
      attempt + 1,
      maxBackoff,
    );
  }
}

import * as crypto from 'node:crypto';
import * as fs from 'node:fs/promises';
import * as path from 'node:path/posix';
import { AppLogger } from '@/common/logger/app-logger';
import { RedisMessage } from '@/dapr/interface/redis-message-data.interface';

/**
 * Hook called before application shutdown
 * @param logger logger
 * @param inMemoryQueue inMemory queue
 * @param queueBackupBasePath queue backup base path
 * @param microServiceName micro service name
 * @param signal killing signal
 */
export async function beforeApplicationShutdown(
  logger: AppLogger,
  inMemoryQueue: Record<string, Array<RedisMessage>>,
  queueBackupBasePath: string,
  microServiceName: string,
  signal: string,
): Promise<void> {
  const context = {
    method: 'beforeApplicationShutdown',
    service: 'daprService',
  };
  try {
    logger.log(
      `beforeApplicationShutdown - Received signal ${signal}`,
      context,
    ); // E.g. "SIGINT"

    await Promise.all(
      Object.keys(inMemoryQueue).map(async (key) => {
        const dataQueue = inMemoryQueue[key];
        const uniqueId = crypto.randomUUID();

        // Adjust the file path to include the queue name and UUID in the filename
        const filePath = path.join(
          queueBackupBasePath,
          microServiceName,
          `queue-${key}-${uniqueId}.json`,
        );

        try {
          // Ensure the base folder exists (not queue specific anymore)
          await fs.mkdir(path.join(queueBackupBasePath, microServiceName), {
            recursive: true,
          });

          // Write the JSON data to the file
          if (dataQueue.length > 0) {
            await fs.writeFile(
              filePath,
              JSON.stringify(dataQueue, undefined, 2),
            );

            logger.log(
              `beforeApplicationShutdown - Successfully backed up ${key} queue to ${filePath}.`,
              context,
            );
          } else {
            logger.log(
              `beforeApplicationShutdown - No data found for queue${key}`,
              context,
            );
          }
        } catch (fileError) {
          logger.error(
            `Error backing up ${key} queue: ${fileError.message}`,
            fileError.stack,
          );
        }
      }),
    );
  } catch (error) {
    logger.error(
      `Error backing up queues: ${error.message}`,
      context,
      error.stack,
    );
  }
}

import { Mutex } from 'async-mutex';

export const pendingMessageStats = {
  count: 0,
};

export const pendingMessageCountMutex = new Mutex();

/**
 * Increment the general counter
 */
export function incrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count += 1;
  });
}

/**
 * Decrement the general counter
 */
export function decrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count -= 1;
  });
}

/**
 * Return count property from pendingMessageStats
 * @returns count property
 */
export function getPendingMessagesCount(): number {
  return pendingMessageStats.count;
}

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/common/logger/app-logger';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';

/**
 * Checks if the ALERT_CODE is 'Reschedule_WK' and ALERT_CATEGORY is 'LOGISTICS'
 * @param logger - The application logger
 * @param context - The job log context
 * @param record - The payload data
 * @returns - Returns true if the condition is satisfied, false otherwise
 */
export function checkAlertCodeAndCategory(
  logger: AppLogger,
  context: JobsLogContext,
  record: CombinedDtoWithIndex,
): boolean {
  try {
    const { ALERT_CODE, ALERT_CATEGORY } = record;
    const isValid =
      ALERT_CODE === 'Reschedule_WK' && ALERT_CATEGORY === 'LOGISTICS';
    if (!isValid) {
      const alertIdMessage = `Alert id ${record.alertId}`;
      const alertConfigMessage = `Alert config id ${record.alertConfigId}`;
      logger.verbose(
        `${record.alertId ? alertIdMessage : alertConfigMessage} with code or category is not valid. ALERT_CODE: ${ALERT_CODE}, ALERT_CATEGORY: ${ALERT_CATEGORY}`,
        context,
      );
    }
    return isValid;
  } catch (error) {
    logger.error(
      `Error in checkAlertCodeAndCategory: ${error.message}`,
      context,
    );
    return false;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/common/logger/app-logger';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';

/**
 * Check if payload is consistent
 * @param logger Application logger
 * @param context Job Log Context
 * @param record - The record to check for consistency
 * @returns - Returns true if the payload is consistent, false otherwise
 */
export function checkPayloadConsistency(
  logger: AppLogger,
  context: JobsLogContext,
  record: CombinedDtoWithIndex,
): boolean {
  logger.verbose(`Checking consistency...`, context);
  if (!record) {
    logger.verbose(`Error: payload is empty`, context);
    return false;
  }

  const { __source_table: sourceTable, __op: operation } = record;
  if (!sourceTable) {
    logger.verbose(`Error: Table source undefined`, context);
    return false;
  }

  if (!['c', 'u', 'r'].includes(operation ?? '')) {
    if (operation === 'd' && sourceTable === 'ITEM_GROUP_MEMBER') {
      return true;
    }
    logger.verbose(`Error: Unknown operation ${operation}`, context);
    return false;
  }

  return true;
}

import { AppLogger } from '@/common/logger/app-logger';
import { MappedOutput } from '@/common/mapping/interface/mapping.model';
import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';

/**
 * Check if plant consistency
 * @param logger - Application logger
 * @param mappedData - The mapped data
 * @param listPlant - List Plant
 * @param excludedPlants excluded plants set
 * @returns - Returns true if plant is consistent, false otherwise
 */
export function checkPlantConsistency(
  logger: AppLogger,
  mappedData: MappedOutput,
  listPlant: Array<PlantsResponseDto>,
  excludedPlants?: Set<string>,
): boolean {
  try {
    const context = {
      method: 'checkPlantConsistency',
      service: 'checkPlantConsistency',
    };

    const plantCode = mappedData?.plant;
    if (excludedPlants && excludedPlants.size > 0 && plantCode !== undefined) {
      const normalized = String(plantCode).trim();
      if (normalized && excludedPlants.has(normalized)) {
        return false;
      }
    }

    const plantCheck = listPlant.some((plant: PlantsResponseDto) => {
      return plant.plantId === Number(mappedData.plant);
    });
    if (!plantCheck) {
      logger.verbose(
        `Plant ${mappedData.plant} is not defined in the plant list ${JSON.stringify(listPlant)} `,
        context,
      );
    }
    return plantCheck;
  } catch (error) {
    logger.error(`Error processing message: ${error}`, error.stack);
  }
  return false; // Return false in case of an error or if no other return statement is reached
}

import { AppLogger } from '@/common/logger/app-logger';
import { IngestionEventTrackingDTO } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.dto.';
import { IngestionEventTrackingService } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.service';

/**
 *
 * @param logger App logger²
 * @param ingestionEventTrackingService to check timestamp
 * @param ingestionEventTracking - The Ingestion Event tracking Dto
 * @returns - Returns a promise that resolves to a boolean indicating the success of the operation.
 */
export async function validateAndTrackChanges(
  logger: AppLogger,
  ingestionEventTrackingService: IngestionEventTrackingService,
  ingestionEventTracking: IngestionEventTrackingDTO,
): Promise<boolean> {
  const context = {
    method: 'validateAndTrackChanges',
    service: 'validateAndTrackChanges',
  };
  if (!ingestionEventTracking) {
    logger.error(
      'Validation failed: ingestionEventTracking is undefined.',
      context,
    );
    return false;
  }
  const {
    changeLastLsn,
    lastTimestamp,
    destinationTable,
    hashKey,
    keys,
    sourceTable,
  } = ingestionEventTracking;
  if (
    changeLastLsn === undefined ||
    lastTimestamp === undefined ||
    hashKey === undefined ||
    keys === undefined ||
    sourceTable === undefined
  ) {
    logger.error(
      `Validation failed: Missing properties in ingestionEventTracking. ` +
        `Received changeLastLsn: ${changeLastLsn}, lastTimestamp: ${lastTimestamp}, ` +
        `destinationTable: ${destinationTable}, hashKey: ${hashKey}, keys: ${keys}, sourceTable: ${sourceTable}.`,
      context,
    );
    return false;
  }
  try {
    const isDataCurrent =
      await ingestionEventTrackingService.verifyAndTrackIngestionEventTrackingCache(
        ingestionEventTracking,
      );

    if (!isDataCurrent) {
      logger.warn(
        `Outdated data detected for table "${sourceTable}". ` +
          `Timestamp: ${lastTimestamp}, Last LSN: ${changeLastLsn}.`,
        context,
      );
      return false;
    }

    return true;
  } catch (error) {
    logger.error(
      `Error while verifying and tracking ingestion event for table "${sourceTable}": ${error.message}`,
      context,
      error.stack,
    );
    return false;
  }
}

