@Module({
  exports: [AlertConfigService],
  imports: [TypeOrmModule.forFeature([AlertConfig])],
  providers: [AlertConfigService],
})
export class AlertConfigModule {}

import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AlertConfig } from './alert-config.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class AlertConfigService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: AlertConfigService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(AlertConfig)
    private readonly alertConfigRepo: Repository<AlertConfig>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('alertConfig.c')
  private async create(payload: AlertConfig): Promise<void> {
    const context = AlertConfigService.createLogContext(
      'create',
      payload?.plant,
      String(payload?.alertConfigId),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    try {
      const { ...alertConfigData } = payload;
      const startTime = Date.now();
      await this.alertConfigRepo.save(alertConfigData);
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert-config',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert-config',
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('alertConfig.u')
  private async updateByAlertConfigIdAndPlant(
    payload: AlertConfig,
  ): Promise<void> {
    const context = AlertConfigService.createLogContext(
      'updateByAlertConfigIdAndPlant',
      payload?.plant,
      String(payload?.alertConfigId),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    try {
      const { alertConfigId, plant } = payload;
      const { ...alertConfigData } = payload;
      const startTime = Date.now();
      const alertConfigEntity = await this.alertConfigRepo.findOne({
        where: { alertConfigId, plant },
      });

      if (!alertConfigEntity) {
        return undefined;
      }
      await this.alertConfigRepo.update(
        { alertConfigId, plant },
        alertConfigData,
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert-config',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert-config',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating AlertConfig: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('alertConfig.r')
  private async readSnapshot(payload: AlertConfig): Promise<void> {
    const context = AlertConfigService.createLogContext(
      'readSnapshot',
      payload?.plant,
      String(payload?.alertConfigId),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    try {
      const { alertConfigId, plant, ...alertConfigData } = payload;
      const startTime = Date.now();
      await this.alertConfigRepo.manager.transaction(
        async (transactionalEntityManager) => {
          // Find the existing entity
          let alertConfigEntity = await transactionalEntityManager.findOne(
            AlertConfig,
            {
              where: { alertConfigId, plant },
            },
          );
          if (alertConfigEntity) {
            // Update the entity's fields
            Object.assign(alertConfigEntity, alertConfigData);
            this.customLogger.debug(
              `AlertConfig with ID ${alertConfigId} and Plant ID ${plant} is found`,
              context,
            );
          } else {
            this.customLogger.debug(
              `AlertConfig with ID ${alertConfigId} and Plant ID ${plant} is not found and will be inserted`,
              context,
            );
            // Create a new entity
            alertConfigEntity = transactionalEntityManager.create(AlertConfig, {
              alertConfigId,
              plant,
              ...alertConfigData,
            });
          }
          // Save the entity (inserts if new, updates if existing)
          await transactionalEntityManager.save(alertConfigEntity);
          this.customLogger.debug(
            `Successfully upserted AlertConfig with ID ${alertConfigId} and Plant ID ${plant}`,
            context,
          );
        },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert-config',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert-config',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating AlertConfig: ${error.message}`,
        context,
      );
    }
    return undefined;
  }
}

