import { Repository } from 'typeorm';
import { Alert } from './alert.entity';
import { AppLogger } from '@/common/logger/app-logger';
import { PickingOrderService } from '@/modules/picking-order/picking-order.service';

@Injectable()
export class AlertService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: AlertService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(Alert)
    private readonly alertRepo: Repository<Alert>,
    private readonly pickingService: PickingOrderService,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('alert.c')
  private async create(payload: Alert): Promise<void> {
    const context = AlertService.createLogContext(
      'create',
      payload?.plant,
      String(payload?.alertId),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    try {
      const { plant, pickingOrderId, ...alertData } = payload;

      // Re-add `plant` and `pickingOrderId` to `alertData`
      const completeAlertData = { ...alertData, pickingOrderId, plant };

      const startTime = Date.now();
      await this.alertRepo.save(completeAlertData); // Save the complete object
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert',
      );

      const result = await this.pickingService.updateAlertedWK(
        plant,
        pickingOrderId,
      );

      this.customLogger.debug(`Alert upsertion result : ${result}`, context);
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('alert.u')
  private async updateByAlertIdAndplant(payload: Alert): Promise<void> {
    const context = AlertService.createLogContext(
      'updateByAlertIdAndplant',
      payload?.plant,
      String(payload?.alertId),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    try {
      const { alertId, plant } = payload;
      const { ...alertData } = payload;
      const startTime = Date.now();
      const alertEntity = await this.alertRepo.findOne({
        where: { alertId, plant },
      });
      if (!alertEntity) {
        return undefined;
      }
      await this.alertRepo.update({ alertId, plant }, alertData);
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating Alert: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('alert.r')
  private async readSnapshot(payload: Alert): Promise<void> {
    const context = AlertService.createLogContext(
      'readSnapshot',
      payload?.plant,
      String(payload?.alertId),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    try {
      const { alertId, plant, ...alertData } = payload;
      const startTime = Date.now();
      await this.alertRepo.manager.transaction(
        async (transactionalEntityManager) => {
          // Find the existing entity
          let alertEntity = await transactionalEntityManager.findOne(Alert, {
            where: { alertId, plant },
          });
          if (alertEntity) {
            // Update the entity's fields
            Object.assign(alertEntity, alertData);
            this.customLogger.debug(
              `Alert with ID ${alertId} and Plant ID ${plant} is found`,
              context,
            );
          } else {
            this.customLogger.debug(
              `Alert with ID ${alertId} and Plant ID ${plant} is not found and will be inserted`,
              context,
            );
            // Create a new entity
            alertEntity = transactionalEntityManager.create(Alert, {
              alertId,
              plant,
              ...alertData,
            });
          }
          // Save the entity (inserts if new, updates if existing)
          await transactionalEntityManager.save(alertEntity);
          this.customLogger.debug(
            `Successfully upserted Alert with ID ${alertId} and Plant ID ${plant}`,
            context,
          );
        },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'alert',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating Alert: ${error.message}`,
        context,
      );
    }
    return undefined;
  }
}

