@Injectable()
export class PickingOrderService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: PickingOrderService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(PickingOrder)
    private readonly pickingRepository: Repository<PickingOrder>,
    private readonly customLogger: AppLogger,
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  @OnEvent('pickingOrder.c')
  private async create(payload: PickingOrder): Promise<void> {
    const context = PickingOrderService.createLogContext(
      'create',
      payload?.plant,
      payload?.pickingOrderId,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const operationInfo = {
      name: 'Create PickingOrder (SQL)',
      srcLocation: 'pickingOrder.c',
    };

    try {
      const { ...pickingOrderData } = payload;
      const reformattedPayload = substring(
        pickingOrderData,
        'material',
        'workcenter',
        'status',
      );

      const startTime = Date.now();
      await execAndLog(
        this.customLogger,
        context,
        () => this.pickingRepository.save(reformattedPayload),
        operationInfo,
        { reformattedPayload },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'picking-order',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'picking-order',
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('pickingOrder.u')
  private async updateByPickingIdAndPlant(
    payload: PickingOrder,
  ): Promise<void> {
    const context = PickingOrderService.createLogContext(
      'updateByPickingIdAndPlant',
      payload?.plant,
      payload?.pickingOrderId,
    );
    const { pickingOrderId, plant } = payload;
    const operationInfo = {
      name: '',
      srcLocation: 'pickingOrder.u',
    };

    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    try {
      const { ...pickingOrderData } = payload;
      const reformattedPayload = substring(
        pickingOrderData,
        'material',
        'workcenter',
        'status',
      );
      // Update the entity
      operationInfo.name = 'Update PickingOrder (SQL)';
      const startTime = Date.now();
      const result = await execAndLog(
        this.customLogger,
        context,
        () =>
          this.pickingRepository.update(
            { pickingOrderId, plant },
            reformattedPayload,
          ),
        operationInfo,
        { reformattedPayload },
      );
      if (result.affected === 0) {
        await this.pickingRepository.insert(reformattedPayload);
      }
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'picking-order',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'picking-order',
      );
      if (reformattedPayload.customStatus === 'SFG_PIK_CLOSED') {
        const message = {
          pickingOrderId: pickingOrderData.pickingOrderId,
          plant: pickingOrderData.plant,
        };
        await this.publishMessageService.publishMessageSfgClosed(
          this.eventhubService.topicSfgClosedOrders,
          message,
        );
      }
    } catch (error) {
      this.customLogger.error(
        `Error updating picking order: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  public async updateAlertedWK(
    plant: number,
    pickingOrderId: string,
  ): Promise<string | undefined> {
    const context = PickingOrderService.createLogContext(
      'updateAlertedWK',
      plant,
      pickingOrderId,
    );
    let message = '';
    try {
      const creteria = { pickingOrderId, plant };
      const newValue = { alertCreated: true };

      const startTime = Date.now();
      const result = await this.pickingRepository.update(creteria, newValue);
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(plant),
        'picking-order',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(plant),
        'picking-order',
      );
      if (result.affected && result.affected > 0) {
        message = 'SUCCESS';
        this.customLogger.debug(
          `Successfully updated alert status for picking order ${pickingOrderId}`,
          context,
        );
        return message;
      }
      message = 'ERROR';
      this.customLogger.warn(
        `No picking order found for updating alert status with ID ${pickingOrderId} and Plant ID ${plant}`,
        context,
      );
      return message;
    } catch (error) {
      message = `Failed to update picking order: ${error.message}`;
      this.customLogger.error(message, context);
      return message;
    }
  }

  @OnEvent('pickingOrder.r')
  private async readSnapshot(payload: PickingOrder): Promise<void> {
    const context = PickingOrderService.createLogContext(
      'readSnapshot',
      payload?.plant,
      payload?.pickingOrderId,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const operationInfo = {
      name: 'pickingOrder readSnapshot (SQL)',
      srcLocation: 'pickingOrder.r readSnapshot',
    };

    try {
      const { ...pickingOrderData } = payload;
      const reformattedPayload = substring(
        pickingOrderData,
        'material',
        'workcenter',
        'status',
      );
      const { plant, pickingOrderId, ...pickingReforamttedPayload } =
        reformattedPayload;
      // Ensure 'customStatus' is set to an empty string if null
      const transactionPromise = this.pickingRepository.manager.transaction(
        async (transactionalEntityManager) => {
          // Find the existing entity
          let pickingOrder = await transactionalEntityManager.findOne(
            PickingOrder,
            {
              where: {
                pickingOrderId: pickingOrderData.pickingOrderId,
                plant: pickingOrderData.plant,
              },
            },
          );

          if (pickingOrder) {
            // Update the entity's fields
            Object.assign(pickingOrder, pickingReforamttedPayload);
            this.customLogger.debug(
              `Picking Order ${pickingOrderData.pickingOrderId} with Plant ID ${plant} is found`,
              context,
            );
          } else {
            this.customLogger.debug(
              `Picking Order ${pickingOrderData.pickingOrderId} with Plant ID ${plant} is not found and will be inserted`,
              context,
            );
            // Create a new entity
            pickingOrder = transactionalEntityManager.create(PickingOrder, {
              pickingOrderId: pickingOrderData.pickingOrderId,
              plant: pickingOrderData.plant,
              ...pickingReforamttedPayload,
            });
          }
          this.customLogger.debug(JSON.stringify(pickingOrder), context);
          // Save the entity (inserts if new, updates if existing)
          await transactionalEntityManager.save(pickingOrder);
        },
      );

      const startTime = Date.now();
      await execAndLog(
        this.customLogger,
        context,
        () => transactionPromise,
        operationInfo,
        {
          pickingOrderId,
        },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'picking-order',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'picking-order',
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting Picking Order: ${error.message}`,
        context,
      );
    }
    return undefined;
  }
}

