// Probes.service.ts
import { RedisConnectionService, RedisClientInstance } from '@mesx/common-lib';
import { Injectable, Logger } from '@nestjs/common';
import axios from 'axios';
import { Response } from 'express';
import { ProbesConfigService } from '@/config/probes/probes.service';

@Injectable()
export class ProbesService {
  private readonly healthMessage = 'mesx/order-di [OK]';

  public constructor(
    private readonly probesConfigService: ProbesConfigService,
    private readonly redisConnectionFactory: RedisConnectionService,
  ) {}

  public getHello(): string {
    return this.healthMessage;
  }

  /**
   * Performs a health check by calling the DAPR health endpoint
   * @param resp Express response object to send the result
   * @returns Promise resolving to void
   */
  public async checkHealth(resp: Response): Promise<void> {
    try {
      const daprStatus = await this.checkDaprHealth();
      const redisStatus = await this.checkRedisHealth();

      if (!redisStatus.success) {
        resp.status(500).json({ reason: redisStatus.reason });
        return;
      }

      // All systems healthy
      resp.status(200).json(`Status Code: ${daprStatus}`);
    } catch (error) {
      const statusCode = error.response?.status ?? 'Unknown';

      if (statusCode === 'Unknown') {
        Logger.error(
          `Dapr health check failed with unknown error: ${error.message}`,
          error.stack,
        );
        resp.status(500).json({
          reason: `Dapr health check failed: ${error.message}`,
        });
      } else {
        const responseBody = error.response?.data ?? 'No response body';
        const statusText = error.response?.statusText ?? 'No status text';

        Logger.error(
          `Dapr health check failed with status code: ${statusCode}, status text: ${statusText}, response body: ${responseBody}`,
        );
        resp.status(500).json({
          reason: 'Dapr health check failed',
          statusCode,
          statusText,
          responseBody,
        });
      }
    }
  }

  private async checkDaprHealth(): Promise<number> {
    const response = await axios.get(this.probesConfigService.daprCheckUrl, {
      timeout: this.probesConfigService.checkTimeoutMs,
    });
    return response.status;
  }

  private async checkRedisHealth(): Promise<
    { success: true } | { success: false; reason: string }
  > {
    let client: RedisClientInstance | undefined;
    try {
      client = await this.redisConnectionFactory.getClient();
      const ping = await client.ping();

      if (ping !== 'PONG') {
        Logger.error(`Redis health check unexpected ping: ${ping}`);
        return {
          success: false,
          reason: `Redis ping returned unexpected value: ${ping}`,
        };
      }

      return { success: true };
    } catch (error) {
      Logger.error(
        `Redis health check failed: ${error?.message ?? error}`,
        error?.stack,
      );
      return {
        success: false,
        reason: `Redis check failed: ${error?.message ?? 'Unknown error'}`,
      };
    } finally {
      if (client) {
        await this.redisConnectionFactory.releaseClient(client);
      }
    }
  }
}

