import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { substring } from '@/common/mapping/utils/formatting.utils';
import { PickingOrder } from '@/modules/picking-order/picking-order.entity';
import { ProductionOrder } from '@/modules/production-order/production-order.entity';

@Injectable()
export class ProductionOrderService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: ProductionOrderService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(ProductionOrder)
    private readonly productionRepository: Repository<ProductionOrder>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('productionOrder.c')
  private async create(payload: ProductionOrder): Promise<void> {
    const context = ProductionOrderService.createLogContext(
      'create',
      payload?.plant,
      payload?.productionOrderId,
    );

    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const operationInfo = {
      name: 'Create ProductionOrder (SQL)',
      srcLocation: 'productionOrder.c',
    };

    try {
      const { ...productionOrderData } = payload;
      const reformattedPayload = substring(
        productionOrderData,
        'material',
        'workcenter',
        'status',
      );

      const startTime = Date.now();
      await execAndLog(
        this.customLogger,
        context,
        () => this.productionRepository.save(reformattedPayload),
        operationInfo,
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'production-order',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'production-order',
      );

      // Update related WK
      await this.updateRelatedPickingOrder(
        payload?.plant,
        payload?.productionOrderId,
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  @OnEvent('productionOrder.u')
  private async updateByProductionIdAndPlant(
    payload: ProductionOrder,
  ): Promise<void> {
    const context = ProductionOrderService.createLogContext(
      'updateByProductionIdAndPlant',
      payload?.plant,
      payload?.productionOrderId,
    );

    const operationInfo = {
      name: '',
      srcLocation: 'productionOrder.u',
    };

    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const { productionOrderId, plant } = payload;

    try {
      const { ...productionOrderData } = payload;
      const reformattedPayload = substring(
        productionOrderData,
        'material',
        'workcenter',
        'status',
      );

      operationInfo.name = 'Update ProductionOrder (SQL)';
      // Update the entity with the reformatted payload
      const startTime = Date.now();
      const result = await execAndLog(
        this.customLogger,
        context,
        () =>
          this.productionRepository.update(
            { plant, productionOrderId },
            reformattedPayload,
          ),
        operationInfo,
        { reformattedPayload },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'production-order',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'production-order',
      );
      if (result.affected === 0) {
        return undefined;
      }

      // Update related WK
      await this.updateRelatedPickingOrder(plant, productionOrderId);
    } catch (error) {
      this.customLogger.error(
        `Error updating production order: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  @OnEvent('productionOrder.r')
  private async readSnapshot(payload: ProductionOrder): Promise<void> {
    const context = ProductionOrderService.createLogContext(
      'updateByProductionIdAndPlant',
      payload?.plant,
      payload?.productionOrderId,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const operationInfo = {
      name: 'ProductionOrder readSnapshot (SQL)',
      srcLocation: 'productionOrder.r readSnapshot',
    };

    try {
      const { ...productionOrderData } = payload;

      const reformattedPayload = substring(
        productionOrderData,
        'material',
        'workcenter',
        'status',
      );
      const { plant, productionOrderId, ...productionReforamttedPayload } =
        reformattedPayload;

      const transactionPromise = this.productionRepository.manager.transaction(
        async (transactionalEntityManager) => {
          // Find the existing entity
          let productionOrder = await transactionalEntityManager.findOne(
            ProductionOrder,
            {
              where: {
                plant: productionOrderData.plant,
                productionOrderId: productionOrderData.productionOrderId,
              },
            },
          );
          if (productionOrder) {
            // Update the entity's fields
            Object.assign(productionOrder, productionReforamttedPayload);
            this.customLogger.debug(
              `Production Order ${payload?.productionOrderId} with Plant ID ${plant} is founded`,
              context,
            );
          } else {
            this.customLogger.debug(
              `Production Order ${payload?.productionOrderId} with Plant ID ${plant} is not found and will be inserte`,
              context,
            );
            // Create a new entity
            productionOrder = transactionalEntityManager.create(
              ProductionOrder,
              {
                plant: productionOrderData.plant,
                productionOrderId: productionOrderData.productionOrderId,
                ...productionReforamttedPayload,
              },
            );
          }

          // Save the entity (inserts if new, updates if existing)
          await transactionalEntityManager.save(productionOrder);
          this.customLogger.debug(
            `Successfully upserted Production Order ${payload?.productionOrderId} and Plant ID ${plant}`,
            context,
          );
        },
      );

      const startTime = Date.now();
      await execAndLog(
        this.customLogger,
        context,
        () => transactionPromise,
        operationInfo,
        {
          productionOrderId,
        },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'production-order',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'production-order',
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting Production Order: ${error.message}`,
        context,
        error.stack,
      );
      throw new HttpException(
        `error in upserting data ${error}`,
        HttpStatus.BAD_REQUEST,
      );
    }
    return undefined;
  }

  private async updateRelatedPickingOrder(
    plant: number,
    productionOrderId: string,
  ): Promise<void> {
    const startTime = Date.now();
    const order = await this.productionRepository.findOne({
      where: { plant, productionOrderId },
    });

    if (!order) return;

    const relatedWK = order.relatedOrder ?? '';

    if (relatedWK) {
      const hasStatus502 = await this.productionRepository.exists({
        where: { plant, relatedOrder: relatedWK, status: '502' },
      });

      const pickingRepository =
        this.productionRepository.manager.getRepository(PickingOrder);
      await pickingRepository.update(
        {
          plant,
          pickingOrderId: relatedWK,
          containsHoldChildren: !hasStatus502,
        }, // Criteria
        { containsHoldChildren: hasStatus502 }, // Update payload
      );
    }
    const sqlDuration = Date.now() - startTime;
    telemetryMetrics.trackEventProcessingDuration(
      sqlDuration,
      PROCESSING_STATUS.SQL,
      String(plant),
      'production-order-related-picking',
    );
    telemetryMetrics.trackEventProcessed(
      PROCESSING_STATUS.SQL,
      String(plant),
      'production-order-related-picking',
    );
  }
}

