  public constructor(
    @InjectRepository(Workcenter)
    private readonly workcenterRepository: Repository<Workcenter>,
    private readonly customLogger: AppLogger,
  ) {}

  public async findWorkcenter(
    payload: KeysValueArray,
  ): Promise<string | undefined> {
    this.context.method = 'findWorkcenter';
    const { plant, workcenterId } = payload;
    try {
      const result: string | undefined = await this.workcenterRepository
        .createQueryBuilder('workcenter')
        .select('workcenter_id as workcenterId')
        .where(
          'workcenter.plant= :plant AND workcenter.workcenter_id=:workcenterId',
          { plant, workcenterId },
        )
        .getRawOne();
      return result;
    } catch (error) {
      this.customLogger.error(error, this.context);
      throw new HttpException(
        ' Query get workcenter Failed',
        HttpStatus.BAD_REQUEST,
      );
    }
  }

  @OnEvent('workcenter.c')
  private async create(payload: Workcenter): Promise<void> {
    this.context.method = 'create';
    if (!payload)
      return this.customLogger.error(
        `payload is empty ${payload}`,
        this.context,
      );
    try {
      const { ...workcenterData } = payload;
      const startTime = Date.now();

      await this.workcenterRepository.save(workcenterData);
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'workcenter',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'workcenter',
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message : ${error.message}`,
        this.context,
        error,
      );
    }
    return undefined;
  }

  @OnEvent('workcenter.u')
  private async updateByWorkcenterIdAndPlant(
    payload: Workcenter,
  ): Promise<void> {
    this.context.method = 'updateByWorkcenterIdAndPlant';
    const startTime = Date.now();

    if (!payload) {
      this.customLogger.error('Payload is empty', this.context);
      return;
    }
    const { workcenterId, plant, ...workcenterData } = payload;

    if (!workcenterId || !plant) {
      this.customLogger.error(
        'Invalid payload: missing workcenterId or plant',
        this.context,
      );
      return;
    }

    try {
      await this.workcenterRepository.manager.transaction(
        async (transactionalEntityManager) => {
          // Check if the workcenter already exists
          let workcenter = await transactionalEntityManager.findOne(
            Workcenter,
            {
              where: { plant, workcenterId },
            },
          );

          if (workcenter) {
            // Update only the non-primary key fields
            Object.assign(workcenter, workcenterData);
          } else {
            // Create a new entity with the primary key and data
            workcenter = transactionalEntityManager.create(Workcenter, {
              plant,
              workcenterId,
              ...workcenterData,
            });
          }

          // Save the entity (inserts if new, updates if existing)
          await transactionalEntityManager.save(workcenter);
          const sqlDuration = Date.now() - startTime;
          telemetryMetrics.trackEventProcessingDuration(
            sqlDuration,
            PROCESSING_STATUS.SQL,
            String(payload.plant),
            'workcenter',
          );
          telemetryMetrics.trackEventProcessed(
            PROCESSING_STATUS.SQL,
            String(payload.plant),
            'workcenter',
          );
        },
      );

      // Publish workcenter message outside the transaction
    } catch (error) {
      this.customLogger.error(
        `Error updating workcenter: ${error.message}`,
        this.context,
      );
    }
  }

  @OnEvent('workcenter.r')
  private async readSnapshot(payload: Workcenter): Promise<void> {
    this.context.method = 'readSnapshot';
    if (!payload)
      return this.customLogger.error(
        `payload is empty${payload}`,
        this.context,
      );

    const { workcenterId, plant, ...workcenterData } = payload;

    if (!workcenterId || !plant) {
      this.customLogger.error(
        'Invalid payload: missing workcenterId or plant',
        this.context,
      );
      return undefined;
    }
    try {
      await this.workcenterRepository.manager.transaction(
        async (transactionalEntityManager) => {
          // Find the existing entity
          let workcenter = await transactionalEntityManager.findOne(
            Workcenter,
            {
              where: { plant, workcenterId },
            },
          );
          if (workcenter) {
            // Update the entity's fields
            Object.assign(workcenter, workcenterData);
          } else {
            // Create a new entity
            workcenter = transactionalEntityManager.create(Workcenter, {
              plant,
              workcenterId,
              ...workcenterData,
            });
          }
          // Save the entity (inserts if new, updates if existing)
          await transactionalEntityManager.save(workcenter);
        },
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating UAP: ${error.message}`,
        this.context,
      );
    }
